1	//! The cargo registry adapter: how a cargo publish is observed, classified and run.
2	
3	use super::*;
4	
5	pub(super) struct CargoRegistry;
6	
7	/// The name the *cargo* client knows this registry by. Callisto's logical
8	/// `cratesIo` key is cargo's built-in `crates-io`; every other key is spelled
9	/// the same in `.cargo/config.toml` as it is in `callisto.toml`.
10	/// The cargo registry name for a logical registry key (`cratesIo` is cargo's `crates-io`).
11	pub fn cargo_registry_name(key: &RegistryKey) -> &str {
12	    if key.as_str() == RegistryKey::CRATES_IO {
13	        "crates-io"
14	    } else {
15	        key.as_str()
16	    }
17	}
18	
19	/// The observation argv: `cargo info NAME@VERSION --registry REGISTRY`.
20	///
21	/// `--registry` is never omitted. Without it `cargo info` resolves the local
22	/// workspace and reports an unpublished member's on-disk version as published
23	/// (`version: X (from ./)`), which is the defect this observation exists to
24	/// avoid; with it, cargo reads only the named registry.
25	///
26	/// `net.retry=0` must precede `info` (cargo ignores it after the subcommand):
27	/// callisto's bounded retry owns retrying, and cargo's own backoff inside each
28	/// attempt made an unreachable registry take ~11s per attempt.
29	pub(super) fn cargo_info_args<'a>(spec: &'a str, registry: &'a str) -> [&'a str; 6] {
30	    ["--config", "net.retry=0", "info", spec, "--registry", registry]
31	}
32	
33	impl RegistryEcosystem for CargoRegistry {
34	    fn ecosystem(&self) -> Ecosystem {
35	        Ecosystem::Cargo
36	    }
37	
38	    fn repository(&self, context: &ProviderContext<'_>, operation: &RegistryPublishOperation) -> Option<String> {
39	        let spec = format!("{}@{}", operation.package_name, operation.version.render());
40	        let registry = cargo_registry_name(&operation.registry.key);
41	        let args = cargo_info_args(&spec, registry);
42	        let cwd = registry_argv::cargo_workspace_dir(context.root(), &operation.package_dir).ok()?;
43	        let output = run_observation(
44	            context.runner(),
45	            programs::CARGO,
46	            &args,
47	            &cwd,
48	            timeouts::REGISTRY_QUERY,
49	            true,
50	        )
51	        .ok()?
52	        .ok()?;
53	        output
54	            .success()
55	            .then(|| cargo_info_repository(&output.stdout))
56	            .flatten()
57	    }
58	
59	    fn can_observe_versions(&self) -> bool {
60	        true
61	    }
62	
63	    /// Runs from the package's Cargo workspace directory, so the same `.cargo/config.toml`
64	    /// registry definitions and credentials the publish effect uses apply --
65	    /// private registries and their auth are cargo's business, not ours.
66	    fn observe_once(
